9	  FileVideo2Icon,
10	  SheetIcon,
11	} from "lucide-react";
12	import React, { useState } from "react";
13	import { cn } from "@/lib/utils";
14	import { Attachment } from "@/types/proto/api/v1/attachment_service_pb";
15	import { getAttachmentThumbnailUrl, getAttachmentType, getAttachmentUrl } from "@/utils/attachment";
16	import SquareDiv from "./kit/SquareDiv";
17	import PreviewImageDialog from "./PreviewImageDialog";
18	
19	interface Props {
20	  attachment: Attachment;
21	  className?: string;
22	  strokeWidth?: number;
23	}
24	
25	const AttachmentIcon = (props: Props) => {
26	  const { attachment } = props;
27	  const [previewImage, setPreviewImage] = useState<{ open: boolean; urls: string[]; index: number }>({
28	    open: false,
29	    urls: [],
30	    index: 0,
31	  });
32	  const resourceType = getAttachmentType(attachment);
33	  const attachmentUrl = getAttachmentUrl(attachment);
34	  const className = cn("w-full h-auto", props.className);
35	  const strokeWidth = props.strokeWidth;
36	
37	  const previewResource = () => {
38	    window.open(attachmentUrl);
39	  };
40	
41	  const handleImageClick = () => {
42	    setPreviewImage({ open: true, urls: [attachmentUrl], index: 0 });
43	  };
44	
45	  if (resourceType === "image/*") {
46	    return (
47	      <>
48	        <SquareDiv className={cn(className, "flex items-center justify-center overflow-clip")}>
49	          <img
50	            className="min-w-full min-h-full object-cover"
51	            src={getAttachmentThumbnailUrl(attachment)}
52	            onClick={handleImageClick}
53	            onError={(e) => {
54	              // Fallback to original image if thumbnail fails
55	              const target = e.target as HTMLImageElement;
56	              if (target.src.includes("?thumbnail=true")) {
57	                console.warn("Thumbnail failed, falling back to original image:", attachmentUrl);
58	                target.src = attachmentUrl;
59	              }
60	            }}
61	            decoding="async"
62	            loading="lazy"
63	          />
64	        </SquareDiv>
65	
66	        <PreviewImageDialog
67	          open={previewImage.open}
68	          onOpenChange={(open) => setPreviewImage((prev) => ({ ...prev, open }))}
69	          imgUrls={previewImage.urls}
70	          initialIndex={previewImage.index}
71	        />
72	      </>
73	    );
74	  }
75	
76	  const getAttachmentIcon = () => {
77	    switch (resourceType) {
78	      case "video/*":
79	        return <FileVideo2Icon strokeWidth={strokeWidth} className="w-full h-auto" />;
80	      case "audio/*":
81	        return <FileAudioIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
82	      case "text/*":
83	        return <FileTextIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
84	      case "application/epub+zip":
85	        return <BookIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
86	      case "application/pdf":
87	        return <BookIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
88	      case "application/msword":
89	        return <FileEditIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
90	      case "application/msexcel":
91	        return <SheetIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
92	      case "application/zip":
93	        return <FileArchiveIcon onClick={previewResource} strokeWidth={strokeWidth} className="w-full h-auto" />;
94	      case "application/x-java-archive":
95	        return <BinaryIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
96	      default:
97	        return <FileIcon strokeWidth={strokeWidth} className="w-full h-auto" />;
98	    }
99	  };
100	
101	  return (
102	    <div onClick={previewResource} className={cn(className, "max-w-16 opacity-50")}>
103	      {getAttachmentIcon()}
104	    </div>
105	  );
106	};
107	
108	export default React.memo(AttachmentIcon);
